head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[xml > M > getChildren]<br/>XPath 로 검색한 노드의 하위 Element 노드들을 태그명과 속성 정보가 담긴 객체 배열로 반환합니다.",
    "validation" : [
        "doc(필수) 파라미터로 XML Document 를 설정할 수 있어야 합니다.",
        "key(필수) 파라미터로 부모 노드를 검색하기 위한 XPath 문자열을 설정할 수 있어야 합니다.",
        "하위 Element 노드 정보를 담은 객체 배열을 반환해야 합니다.",
        "반환 객체는 @tagName 속성에 자식 Element 의 노드명을 포함해야 합니다.",
        "반환 객체에 해당 Element 의 모든 속성이 속성명-속성값 쌍으로 포함되어야 합니다.",
        "XPath 에 일치하는 노드가 없거나 하위 Element 노드가 없으면 빈 배열을 반환해야 합니다.",
    ]
}

scwin.testDoc = null;

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.testDoc = WebSquare.xml.parse(
        "<bookstore>" +
            "<book id='b1' category='fiction'>" +
                "<title lang='eng'>Harry Potter</title>" +
                "<author country='UK'>J.K. Rowling</author>" +
                "<price currency='USD' format='decimal'>29.99</price>" +
            "</book>" +
            "<book id='b2' category='tech'>" +
                "<title lang='eng'>Learning XML</title>" +
            "</book>" +
            "<empty/>" +
        "</bookstore>"
    );
};



scwin.btn_getChildren_onclick = function () {
    let xpath = par_key.getValue();

    var result = WebSquare.xml.getChildren(scwin.testDoc, xpath);

    wf_body_bottom.getObj("scwin").setReturnValue("getChildren(doc, '" + xpath + "')");
    wf_body_bottom.getObj("scwin").setReturnValue("결과 개수 : " + result.length);

    for (var i = 0; i < result.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("[" + i + "] " + JSON.stringify(result[i]));
    }

    if (result.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("빈 배열 반환 확인");
    }
}
